window.createWorkflowUI=function(ctx){
  const {state,esc,money,decimal,button,badge,panel,table,field,form,modal,api,refresh,notify,can,confirmAction,today}=ctx;
  const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
  const criteria={due:'',priority:'',department:'',assignee:''};
  const get=(kind,id)=>state()[kind].find(x=>x.id===id);
  function purchaseForm(){
    const s=state(),products=s.products.filter(p=>!p.archived);if(!s.suppliers.length||!products.length)return notify('Add a supplier and a product first.');
    form('Create a purchase order',field('supplierId','Supplier','','text',s.suppliers.map(x=>[x.id,x.name]))+field('warehouse','Receiving warehouse','','text',s.warehouses.map(x=>[x.id,x.name]))+field('due','Expected receipt',today(),'date',null,true)+'<div class="field wide"><span>Order lines</span><div id="purchase-lines"></div><button type="button" id="add-purchase-line">+ Add another item</button></div>',async b=>{
      const lines=$$('#purchase-lines .purchase-line').map(row=>({productId:row.querySelector('[name=productId]').value,quantity:row.querySelector('[name=quantity]').value,cost:row.querySelector('[name=cost]').value}));await api('purchases',{...b,lines});
    },'Create order');
    function add(){const row=document.createElement('div');row.className='purchase-line form-grid';row.style.cssText='padding:12px 0;border-bottom:1px solid var(--line)';row.innerHTML=field('productId','Product / part',products[0].id,'text',products.map(p=>[p.id,p.name]))+field('quantity','Quantity',1,'number',null,true)+field('cost','Unit cost before tax (₹)',decimal(products[0].cost),'number',null,true)+'<button type="button" class="remove-line">Remove line</button>';row.querySelector('select').onchange=e=>row.querySelector('[name=cost]').value=decimal(products.find(p=>p.id===e.target.value).cost);row.querySelector('button').onclick=()=>row.remove();$('#purchase-lines').append(row);}
    $('#add-purchase-line').onclick=add;add();
  }
  function purchaseView(id){const p=get('purchases',id),receipts=state().receipts.filter(r=>r.purchaseId===id);
    modal(p.number,'<p class="hint">'+esc(p.supplier)+' · '+esc(p.status)+' · Expected '+esc(p.due)+'</p>'+table(['Item','Ordered','Received','Returned','Unit cost'],p.lines.map(l=>'<tr><td>'+esc(l.name)+'</td><td>'+l.quantity+'</td><td>'+(l.received??(p.status==='Received'?l.quantity:0))+'</td><td>'+(l.returned||0)+'</td><td>'+money(l.cost)+'</td></tr>'))+'<div class="section-title">Goods receipts</div>'+receipts.map(r=>'<p class="hint">'+esc(r.number)+' · '+esc(r.date)+' · '+esc(r.actor)+'</p>').join('')+'<div class="form-actions">'+button('History','wf-history','purchases:'+id)+(can('purchases')?(p.status!=='Received'?button('Receive items','wf-receive',id):'')+button('Return to supplier','wf-return',id):'')+(can('documents')?button('Record supplier invoice','wf-bill-new',id):'')+'</div>');
  }
  function receiptForm(id){const p=get('purchases',id),key=crypto.randomUUID();
    form('Receive goods · '+p.number,'<p class="hint wide">Enter only the quantities arriving now. Leave other lines at zero. This receipt cannot be applied twice.</p>'+field('date','Receipt date',today(),'date',null,true)+p.lines.map((l,i)=>field('line'+i,l.name+' · remaining '+(l.quantity-(l.received||0)),l.quantity-(l.received||0),'number')).join(''),b=>api('purchases/receive',{id,key,date:b.date,lines:p.lines.map((l,i)=>({index:i,quantity:b['line'+i]||0}))}),'Confirm receipt');
  }
  function billForm(purchaseId){const p=state().purchases.find(p=>p.id===purchaseId);
    form('Record a supplier invoice',field('supplierId','Supplier',p?.supplierId,'text',state().suppliers.map(s=>[s.id,s.name]))+field('reference','Supplier invoice number','','text',null,true)+field('amount','Invoice total including tax (₹)',p?decimal(p.total):'','number',null,true)+field('date','Invoice date',today(),'date',null,true)+field('due','Payment due',today(),'date',null,true),b=>api('supplier-bills',{...b,purchaseId:p?.id||''}),'Record bill');
  }
  function purchasePanels(){const s=state();return '<div style="margin-top:22px">'+panel('Supplier invoices & payables',s.supplierBills.length?table(['Supplier invoice','Supplier','Due','Total','Paid','Balance','Action'],s.supplierBills.map(b=>'<tr><td>'+esc(b.reference)+'</td><td>'+esc(b.supplier)+'</td><td>'+esc(b.due)+'</td><td>'+money(b.amount)+'</td><td>'+money(b.paid)+'</td><td>'+money(b.amount-b.paid)+'</td><td>'+(can('documents')&&b.paid<b.amount?button('Record payment','wf-supplier-pay',b.id):badge(b.paid>=b.amount?'Paid':'Outstanding',b.paid>=b.amount?'green':'amber'))+'</td></tr>')):'<p class="hint">Record supplier invoices and track their outstanding balances here.</p>',can('documents')?button('+ Supplier invoice','wf-bill-new'):'')+'</div>';}
  function billingPanels(){const s=state();return '<div class="grid-two" style="margin-top:22px">'+panel('Approval inbox',s.approvals.filter(a=>a.status==='Pending'&&s.documents.some(d=>d.id===a.documentId&&d.version===a.documentVersion&&d.status==='Draft')).map(a=>'<div class="activity"><div class="activity-main"><strong>'+esc(a.documentNumber)+'</strong><small>Version '+a.documentVersion+' · Requested by '+esc(a.requester)+'</small></div>'+button('Open invoice','document-view',a.documentId)+(['owner','administrator','manager'].includes(s.user.role)&&a.requestedBy!==s.user.id?button('Review','wf-review',a.id):'')+'</div>').join('')||'<p class="hint">No invoices are waiting for approval.</p>')+panel('Recurring invoice drafts',s.recurring.map(r=>'<div class="activity"><div class="activity-main"><strong>'+esc(r.name)+'</strong><small>'+esc(r.frequency)+' · Next '+esc(r.nextRun)+' · '+(r.active?'Active':'Paused')+'</small></div>'+(can('documents')?button(r.active?'Pause':'Resume','wf-recurring-toggle',r.id):'')+'</div>').join('')||'<p class="hint">Open an invoice and select “Recurring drafts” to create a schedule. Generated documents remain drafts until reviewed and issued.</p>',can('documents')?button('Generate due drafts','wf-recurring-run'):'')+'</div>';}
  function settingsPanels(){const p=state().workflowSettings[0]||{};return '<div style="margin-top:22px">'+panel('Workflow controls','<div class="settings-list"><div><div><strong>Invoice approval before issue</strong><small>A different owner, administrator, or manager must approve the current draft version.</small></div>'+badge(p.invoiceApproval?'Required':'Optional',p.invoiceApproval?'blue':'')+'</div><div><strong>Low-stock activity generation</strong>'+badge(p.lowStock===false?'Paused':'Enabled',p.lowStock===false?'':'green')+'</div><div><strong>Overdue-invoice follow-ups</strong>'+badge(p.overdue===false?'Paused':'Enabled',p.overdue===false?'':'green')+'</div></div>',can('settings')?button('Configure rules','wf-settings'):'')+'</div>';}
  function analyticsPanel(){const s=state(),outgoing=s.supplierPayments.reduce((n,p)=>n+p.amount,0);return panel('Recorded cash movements',table(['Cash received','Supplier payments','Operating expenses','Net recorded movement'],['<tr><td>'+money(s.metrics.received)+'</td><td>'+money(outgoing)+'</td><td>'+money(s.metrics.expenses)+'</td><td>'+money(s.metrics.received-outgoing-s.metrics.expenses)+'</td></tr>']),'','All-time recorded movements only; excludes opening cash, financing, and unrecorded transactions.');}
  function enhanceDocument(d){const actions=$('#modal-content .print-actions');if(!actions)return;actions.insertAdjacentHTML('beforeend',button('Version history','wf-history','documents:'+d.id)+(can('documents')&&d.type==='Invoice'&&d.status!=='Deleted'?button('Recurring drafts','wf-recurring-new',d.id):'')+(can('documents')&&d.status==='Draft'?(d.type==='Invoice'?button('Submit for approval','wf-submit',d.id):'')+button('Delete draft','wf-delete-draft',d.id):''));}
  function filterTask(t){return (!criteria.due||t.due<=criteria.due)&&(!criteria.priority||t.priority===criteria.priority)&&(!criteria.department||t.department===criteria.department)&&(!criteria.assignee||t.assignee===criteria.assignee);}
  function enhanceHome(){const toolbar=$('#content .toolbar');if(!toolbar?.insertAdjacentHTML)return;toolbar.insertAdjacentHTML('afterend','<div class="toolbar" id="activity-filters"><label>Due by <input type="date" name="due" value="'+esc(criteria.due)+'"></label><select name="priority" aria-label="Priority"><option value="">All priorities</option>'+['High','Normal','Low'].map(v=>'<option '+(criteria.priority===v?'selected':'')+'>'+v+'</option>').join('')+'</select>'+['department','assignee'].map(key=>'<select name="'+key+'" aria-label="'+key+'"><option value="">All '+key+'s</option>'+[...new Set(state().tasks.map(t=>t[key]))].filter(Boolean).map(v=>'<option '+(criteria[key]===v?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select>').join('')+button('Clear filters','wf-clear-filters')+'</div>');$$('#activity-filters input,#activity-filters select').forEach(el=>el.onchange=()=>{criteria[el.name]=el.value;ctx.render();});}
  async function action(name,id){
    if(name==='purchase-new'){purchaseForm();return true;}
    if(name==='purchase-view'){purchaseView(id);return true;}
    if(name==='purchase-receive'||name==='wf-receive'){receiptForm(id);return true;}
    if(!name.startsWith('wf-'))return false;
    if(name==='wf-clear-filters'){Object.keys(criteria).forEach(k=>criteria[k]='');ctx.render();}
    else if(name==='wf-return'){const p=get('purchases',id),key=crypto.randomUUID();form('Return goods · '+p.number,field('index','Item','','text',p.lines.map((l,i)=>[i,l.name]))+field('quantity','Quantity to return',1,'number',null,true)+field('reason','Reason','','text',null,true,true)+'<p class="hint wide">This records the physical stock return. Supplier credit/refund accounting is separate.</p>',b=>api('purchases/return',{...b,id,key}),'Record supplier return');}
    else if(name==='wf-bill-new')billForm(id);
    else if(name==='wf-supplier-pay'){const b=get('supplierBills',id),key=crypto.randomUUID();form('Record payment · '+b.reference,field('amount','Amount paid (₹)',decimal(b.amount-b.paid),'number',null,true)+field('date','Payment date',today(),'date',null,true)+field('reference','Unique bank/payment reference','','text',null,true,true)+'<p class="hint wide">This records a payment already made. It does not transfer money.</p>',v=>api('supplier-payments',{...v,billId:id,key}),'Record payment');}
    else if(name==='wf-expense-correct'){const e=get('expenses',id);form('Correct expense',field('description','Description',e.description,'text',null,true)+field('category','Category',e.category,'text',null,true)+field('amount','Amount (₹)',decimal(e.amount),'number',null,true)+field('date','Date',e.date,'date',null,true)+field('reference','Reference',e.reference)+field('reason','Reason for correction','','text',null,true),b=>api('expenses/correct',{...b,id,version:e.version}),'Save correction');}
    else if(name==='wf-history'){const [kind,key]=id.split(':'),versions=await api('history?kind='+encodeURIComponent(kind)+'&id='+encodeURIComponent(key));modal('Version history',versions.map(v=>'<details style="padding:14px 0;border-bottom:1px solid var(--line)"><summary>Version '+v.version+' · '+new Date(v.created).toLocaleString('en-IN')+'</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">'+esc(JSON.stringify({...v.body,company:v.body.company?{...v.body.company,logo:v.body.company.logo?'[company logo]':''}:undefined},null,2))+'</pre></details>').join(''));}
    else if(name==='wf-delete-draft'){const d=get('documents',id);confirmAction('Delete draft '+d.number+'?','The draft will disappear from the active list. Its number and version history are preserved.',()=>api('documents/delete-draft',{id,version:d.version}));}
    else if(name==='wf-submit'){await api('approvals/request',{id});await refresh();ctx.close();notify('Submitted for independent review.');}
    else if(name==='wf-review'){const a=get('approvals',id),d=get('documents',a.documentId);form('Review '+a.documentNumber,'<p class="hint wide">Requested by '+esc(a.requester)+'. Version '+a.documentVersion+'. Current document total: '+money(d.total)+'. The requester cannot approve their own invoice.</p>'+field('status','Decision','Approved','text',['Approved','Rejected'])+field('note','Review notes','','textarea',null,false,true),b=>api('approvals/decide',{...b,id}),'Save review');}
    else if(name==='wf-recurring-new'){form('Schedule recurring invoice drafts',field('name','Schedule name','','text',null,true)+field('frequency','Frequency','Monthly','text',['Monthly','Weekly'])+field('nextRun','First draft date',today(),'date',null,true)+field('endDate','End date (optional)','','date')+field('dueDays','Payment terms (days)',14,'number',null,true)+'<p class="hint wide">Each run creates a draft from a snapshot of this invoice. It does not deduct stock, send email, or collect payment. Review each draft before issuing.</p>',b=>api('recurring',{...b,documentId:id}),'Create schedule');}
    else if(name==='wf-recurring-toggle'){const r=get('recurring',id);await api('recurring/toggle',{id,version:r.version});await refresh();}
    else if(name==='wf-recurring-run'){const r=await api('recurring/run',{});await refresh();notify(r.count+' due drafts generated.');}
    else if(name==='wf-settings'){const p=state().workflowSettings[0]||{};form('Configure workflow controls',field('invoiceApproval','Independent invoice approval',String(!!p.invoiceApproval),'text',[['false','Optional'],['true','Required before issue']])+field('lowStock','Low-stock activity generation',String(p.lowStock!==false),'text',[['true','Enabled'],['false','Paused']])+field('overdue','Overdue-invoice follow-ups',String(p.overdue!==false),'text',[['true','Enabled'],['false','Paused']]),b=>api('workflow-settings',{invoiceApproval:b.invoiceApproval==='true',lowStock:b.lowStock==='true',overdue:b.overdue==='true'}));}
    return true;
  }
  return {action,purchasePanels,billingPanels,settingsPanels,analyticsPanel,enhanceDocument,enhanceHome,filterTask};
};
